def make_bar_chart(cities, values, title, ylabel='', color_map=None,
                   highlight_max=False, highlight_min=False,
                   value_fmt='{:.0f}', orientation='vertical', figsize=(10, 5)):
    fig, ax = plt.subplots(figsize=figsize)
