def make_box_plot(cities_data, title, ylabel='', figsize=(10, 5)):
    """cities_data: {city: Series of prices}"""
    fig, ax = plt.subplots(figsize=figsize)
    cities = list(cities_data.keys())
    data = [cities_data[c] for c in cities]
    colors = [CITY_COLORS.get(c, SECONDARY) for c in cities]

    # Cap at p95 for readability
    capped = []
    for d in data:
        p95 = d.quantile(0.95)
        capped.append(d[d <= p95])

    bp = ax.boxplot(capped, labels=cities, patch_artist=True, widths=0.5,
                    medianprops=dict(color=ACCENT, linewidth=2),
                    whiskerprops=dict(color=MID_TEXT),
                    capprops=dict(color=MID_TEXT),
                    flierprops=dict(marker='o', markerfacecolor=GRID_COLOR, markersize=3, alpha=0.3))

    for patch, color in zip(bp['boxes'], colors):
        patch.set_facecolor(color)
        patch.set_alpha(0.6)

    ax.set_ylabel(ylabel, fontsize=11, color=DARK_TEXT)
    ax.set_title(title, fontsize=13, fontweight='bold', color=PRIMARY, pad=15)
    ax.spines['top'].set_visible(False)
    ax.spines['right'].set_visible(False)
    ax.spines['left'].set_color(GRID_COLOR)
    ax.spines['bottom'].set_color(GRID_COLOR)
    ax.tick_params(colors=MID_TEXT, labelsize=10)
    ax.yaxis.grid(True, color=GRID_COLOR, linestyle='--', alpha=0.7)
    ax.set_axisbelow(True)
    fig.tight_layout()
    return fig_to_base64(fig)


