        price_by_room[city][rt] = {
            'median': rt_price.median(),
            'mean': rt_price.mean(),
            'n': len(rt_price)
        }

# 3. Professional Host Share
pro_host_share = {}
host_dist = {}
for city in city_order:
    city_df = df[df['city'] == city]
    total = len(city_df)
    single = (city_df['calculated_host_listings_count'] == 1).sum()
    small = ((city_df['calculated_host_listings_count'] >= 2) &
             (city_df['calculated_host_listings_count'] < 5)).sum()
    pro = (city_df['calculated_host_listings_count'] >= 5).sum()
    pro_host_share[city] = 100 * pro / total
    host_dist[city] = [100 * single / total, 100 * small / total, 100 * pro / total]

# 4. Guest Demand
avg_rpm = {}
avg_rpm_all = {}
for city in city_order:
    city_df = df[df['city'] == city]
    rpm = city_df['reviews_per_month'].dropna()
