    avg_rpm_all[city] = rpm

# 5. Availability
mean_avail = {}
for city in city_order:
    city_df = df[df['city'] == city]
    mean_avail[city] = city_df['availability_365'].mean()


# ─── Generate Charts ─────────────────────────────────────────────────────────

