# Chart 5: Price by room type (grouped bar for cities with price data)
main_room_types = ['Entire home/apt', 'Private room']
price_grouped = {}
for city in price_cities:
    vals = []
    for rt in main_room_types:
        if city in price_by_room and rt in price_by_room[city]:
