def city_table_row(city, data_dict, fmt='{:,}', highlight_best=False, best_fn=max):
    """Generate a table row for the city KPI summary."""
    val = data_dict.get(city, None)
    is_best = False
    if highlight_best and val is not None:
        valid_vals = [v for v in data_dict.values() if v is not None]
        if valid_vals and val == best_fn(valid_vals):
            is_best = True
    if val is None:
        return f'<td style="text-align:center;color:#999;">N/A</td>'
    cell_style = 'text-align:center;'
    if is_best:
        cell_style += 'font-weight:bold;color:#1e3a5f;background:#e8f4fd;'
    return f'<td style="{cell_style}">{fmt.format(val)}</td>'


